+import { readFileSync } from "node:fs";
+import path from "node:path";
+import { parseTasks } from "./tasks.ts";
+import { planOrder } from "./planner.ts";
+import { TaskPlanError } from "./errors.ts";
+
+const USAGE = "Usage: node src/cli.ts plan <file.json> [--json]";
+
+function printUsageAndExit(code: number): never {
+  process.stderr.write(USAGE + "\n");
+  process.exit(code);
+}
+
+function failUsage(): never {
+  process.stderr.write(USAGE + "\n");
+  process.exit(2);
+}
+
+function main(): void {
+  const args = process.argv.slice(2);
+
+  if (args.length === 0) {
+    failUsage();
+  }
+
+  const command = args[0];
+  if (command !== "plan") {
+    failUsage();
+  }
+
+  const rest = args.slice(1);
+
+  let jsonCount = 0;
+  for (const a of rest) {
+    if (a === "--json") {
+      jsonCount++;
+    } else if (a.startsWith("-")) {
+      // unknown option
+      failUsage();
+    }
+  }
+  if (jsonCount > 1) {
+    failUsage();
+  }
+  const useJson = jsonCount === 1;
+
+  const fileArgs = rest.filter((a) => a !== "--json");
+  if (fileArgs.length !== 1) {
+    failUsage();
+  }
+  const fileArg = fileArgs[0]!;
+
+  const filePath = path.isAbsolute(fileArg) ? fileArg : path.resolve(process.cwd(), fileArg);
+
+  let text: string;
+  try {
+    text = readFileSync(filePath, "utf8");
+  } catch (e) {
+    const err = e as NodeJS.ErrnoException;
+    const reason = err.message ?? String(e);
+    process.stderr.write(`error: ${reason}\n`);
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+
+  let data: unknown;
+  try {
+    data = JSON.parse(text!);
+  } catch (e) {
+    const err = e as Error;
+    const desc = err.message ?? String(e);
+    process.stderr.write(`error INVALID_JSON: ${desc}\n`);
+    process.exit(1);
+  }
+
+  try {
+    const tasks = parseTasks(data);
+    const result = planOrder(tasks);
+    if (useJson) {
+      const out = JSON.stringify({ order: result.order, stages: result.stages });
+      process.stdout.write(out + "\n");
+    } else {
+      if (result.order.length === 0 && result.stages.length === 0) {
+        process.stdout.write("Order:\n");
+      } else {
+        for (let i = 0; i < result.stages.length; i++) {
+          const ids = result.stages[i]!;
+          process.stdout.write(`Stage ${i + 1}: ${ids.join(", ")}\n`);
+        }
+        process.stdout.write(`Order: ${result.order.join(", ")}\n`);
+      }
+    }
+    process.exit(0);
+  } catch (e) {
+    if (e instanceof TaskPlanError) {
+      const code = (e as TaskPlanError).code;
+      const msg = (e as Error).message;
+      process.stderr.write(`error ${code}: ${msg}\n`);
+      process.exit(1);
+    }
+    throw e;
+  }
+}
+
+main();
