+import { CycleError, DuplicateTaskError, UnknownDependencyError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of planning a set of tasks. */
+export interface PlanResult {
+  /** Every task id, in execution order. */
+  order: string[];
+  /** stages[k]: tasks that can run at the earliest in round k */
+  stages: string[][];
+}
+
+export { CycleError, DuplicateTaskError, DuplicateTaskIdError, UnknownDependencyError } from "./errors.ts";
+
+/**
+ * Plans execution order and stages for a set of tasks.
+ * Implements Kahn/topological sort with deterministic priority ordering.
+ * @param tasks - tasks in the shape `parseTasks` returns
+ * @returns order and stages as described in SPEC.md
+ * @throws DuplicateTaskError when ids are duplicated
+ * @throws UnknownDependencyError when a dependency is unknown
+ * @throws CycleError when a cycle exists
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  const n = tasks.length;
+  if (n === 0) return { order: [], stages: [] };
+
+  // R3.1 duplicate ids
+  {
+    const counts = new Map<string, number>();
+    const firstPos = new Map<string, number>();
+    for (let i = 0; i < n; i++) {
+      const id = tasks[i]!.id;
+      if (!counts.has(id)) {
+        counts.set(id, 1);
+        firstPos.set(id, i);
+      } else {
+        counts.set(id, (counts.get(id) ?? 0) + 1);
+      }
+    }
+    const dups: string[] = [];
+    for (const [id, c] of counts) {
+      if (c > 1) dups.push(id);
+    }
+    if (dups.length > 0) {
+      dups.sort((a, b) => (firstPos.get(a) ?? 0) - (firstPos.get(b) ?? 0));
+      throw new DuplicateTaskError(dups);
+    }
+  }
+
+  // Build id -> index map
+  const idToIndex = new Map<string, number>();
+  for (let i = 0; i < n; i++) idToIndex.set(tasks[i]!.id, i);
+
+  // Deduped dependencies per task and adjacency
+  const depsIdx: number[][] = new Array(n);
+  for (let i = 0; i < n; i++) {
+    const raw = tasks[i]!.dependsOn;
+    const seen = new Set<string>();
+    const arr: number[] = [];
+    for (const dep of raw) {
+      if (seen.has(dep)) continue;
+      seen.add(dep);
+      // R3.2 unknown dependency - report earliest task, earliest entry
+      const target = idToIndex.get(dep);
+      if (target === undefined) {
+        throw new UnknownDependencyError(tasks[i]!.id, dep);
+      }
+      arr.push(target);
+    }
+    depsIdx[i] = arr;
+  }
+
+  // Reverse adjacency for Kahn
+  const revAdj: number[][] = Array.from({ length: n }, () => []);
+  const indeg = new Array<number>(n);
+  for (let i = 0; i < n; i++) {
+    const d = depsIdx[i]!;
+    indeg[i] = d.length;
+    for (const depIdx of d) {
+      revAdj[depIdx]!.push(i);
+    }
+  }
+
+  // Priority heap: highest priority first, then input position
+  const heap: number[] = [];
+  function higher(a: number, b: number): boolean {
+    const pa = tasks[a]!.priority;
+    const pb = tasks[b]!.priority;
+    if (pa !== pb) return pa > pb;
+    return a < b;
+  }
+  function heapPush(v: number): void {
+    heap.push(v);
+    let i = heap.length - 1;
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      if (higher(heap[p]!, heap[i]!)) break;
+      const tmp = heap[p]!;
+      heap[p] = heap[i]!;
+      heap[i] = tmp;
+      i = p;
+    }
+  }
+  function heapPop(): number | undefined {
+    if (heap.length === 0) return undefined;
+    const top = heap[0]!;
+    const last = heap.pop()!;
+    if (heap.length > 0) {
+      heap[0] = last;
+      let i = 0;
+      const len = heap.length;
+      while (true) {
+        let largest = i;
+        const l = i * 2 + 1;
+        const r = l + 1;
+        if (l < len && !higher(heap[largest]!, heap[l]!)) largest = l;
+        if (r < len && !higher(heap[largest]!, heap[r]!)) largest = r;
+        if (largest === i) break;
+        const tmp = heap[i]!;
+        heap[i] = heap[largest]!;
+        heap[largest] = tmp;
+        i = largest;
+      }
+    }
+    return top;
+  }
+
+  for (let i = 0; i < n; i++) if (indeg[i] === 0) heapPush(i);
+
+  const orderIdx: number[] = [];
+  while (heap.length > 0) {
+    const u = heapPop()!;
+    orderIdx.push(u);
+    for (const v of revAdj[u]!) {
+      indeg[v]!--;
+      if (indeg[v] === 0) heapPush(v);
+    }
+  }
+
+  if (orderIdx.length !== n) {
+    // Cycle detection via iterative DFS on remaining graph (edges i -> deps)
+    // Find remaining nodes: those not in orderIdx ; indeg >0 indicates remaining
+    // But to be safe use a boolean visited via set of orderIdx
+    const inOrder = new Uint8Array(n);
+    for (const x of orderIdx) inOrder[x] = 1;
+    const state = new Uint8Array(n); // 0 unvisited,1 visiting,2 done
+    const parent = new Int32Array(n);
+    for (let i = 0; i < n; i++) parent[i] = -1;
+
+    // adjacency is depsIdx (filtered to remaining nodes)
+    for (let start = 0; start < n; start++) {
+      if (inOrder[start] === 1) continue;
+      if (state[start] !== 0) continue;
+      // stack of frames
+      type Frame = { v: number; next: number };
+      const stack: Frame[] = [{ v: start, next: 0 }];
+      state[start] = 1;
+      while (stack.length > 0) {
+        const frame = stack[stack.length - 1]!;
+        const v = frame.v;
+        const adj = depsIdx[v]!;
+        if (frame.next < adj.length) {
+          const w = adj[frame.next++]!;
+          // only consider remaining nodes (should all be remaining)
+          if (inOrder[w] === 1) continue;
+          if (state[w] === 0) {
+            state[w] = 1;
+            parent[w] = v;
+            stack.push({ v: w, next: 0 });
+          } else if (state[w] === 1) {
+            // found cycle w ... v -> w
+            const path: number[] = [];
+            let cur: number = v;
+            // collect from v up to w
+            while (cur !== w) {
+              path.push(cur);
+              cur = parent[cur]!;
+              // safety: if cur becomes -1 break (should not happen)
+              if (cur === -1) break;
+            }
+            path.push(w);
+            path.reverse();
+            const cycle = path.map((idx) => tasks[idx]!.id);
+            cycle.push(cycle[0]!);
+            throw new CycleError(cycle);
+          } // else visited done -> ignore
+        } else {
+          state[v] = 2;
+          stack.pop();
+        }
+      }
+    }
+    // Fallback if DFS didn't find cycle (should not happen)
+    throw new CycleError([]);
+  }
+
+  const order = orderIdx.map((i) => tasks[i]!.id);
+
+  // Stages: compute depth (longest path)
+  const depth = new Array<number>(n).fill(0);
+  for (const idx of orderIdx) {
+    const deps = depsIdx[idx]!;
+    if (deps.length === 0) {
+      depth[idx] = 0;
+    } else {
+      let m = -1;
+      for (const d of deps) {
+        const dv = depth[d]!;
+        if (dv > m) m = dv;
+      }
+      depth[idx] = m + 1;
+    }
+  }
+  let maxDepth = 0;
+  for (const d of depth) if (d > maxDepth) maxDepth = d;
+  const groups: number[][] = Array.from({ length: maxDepth + 1 }, () => []);
+  for (let i = 0; i < n; i++) groups[depth[i]!]!.push(i);
+  const stages: string[][] = groups.map((g) => {
+    g.sort((a, b) => {
+      const pa = tasks[a]!.priority;
+      const pb = tasks[b]!.priority;
+      if (pa !== pb) return pb - pa;
+      return a - b;
+    });
+    return g.map((i) => tasks[i]!.id);
+  });
+
+  return { order, stages };
+}
